#!/usr/bin/env node
'use strict';
// ============================================================
// .github/scripts/strip-pr-attribution.js — pull-request descriptions
// carry no tool attribution (owner, 2026-10-25: "delete this Generated by
// Claude Code everywhere").
//
// The GitHub gateway of a cloud coding session appends its own footer to
// every description it writes ("---" and "Generated by [...](...)"), and
// again on every edit, so the session cannot take it out. This runs on
// GitHub's side (.github/workflows/pr-attribution.yml): on a pull request
// that is opened, edited or reopened it strips that pull request's
// description; pushed to main or run by hand it sweeps every pull request
// the repository has. An edit made with the workflow's token starts no
// workflow run, so it never answers itself.
//
//   GITHUB_TOKEN  pull-requests: write
//   REPO          owner/name
//   PR_NUMBER     one pull request; unset or empty: all of them
// ============================================================

// A line that is only attribution: the gateway's footer, the tool's own
// "Generated with" line, a session link, a co-author or session trailer.
const ATTRIBUTION = [
  /^\s*_?\s*(?:🤖\s*)?generated (?:by|with) \[claude(?: code)?\]\([^)]*\)\s*_?\s*$/i,
  /^\s*_?\s*(?:🤖\s*)?generated (?:by|with) claude(?: code)?\.?\s*_?\s*$/i,
  /^\s*<?https:\/\/claude\.ai\/code\/session_[A-Za-z0-9_-]+>?\s*$/i,
  /^\s*co-authored-by:\s*claude\b.*$/i,
  /^\s*claude-session:\s*\S+\s*$/i,
];

// The description without its attribution lines, and without the rule
// ("---") and blank lines they leave at the end. Anything else is kept as
// written.
function stripAttribution(body) {
  if (typeof body !== 'string' || !body) return body;
  const lines = body.split(/\r?\n/);
  const kept = lines.filter(l => !ATTRIBUTION.some(re => re.test(l)));
  if (kept.length === lines.length) return body;
  while (kept.length && /^\s*(?:-{3,}|\*{3,}|_{3,})?\s*$/.test(kept[kept.length - 1])) kept.pop();
  return kept.join('\n');
}

async function gh(token, method, path, body) {
  const res = await fetch(`https://api.github.com/${path}`, {
    method,
    headers: {
      authorization: `Bearer ${token}`,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      ...(body ? { 'content-type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const remaining = Number(res.headers.get('x-ratelimit-remaining'));
  if (!res.ok) throw new Error(`${method} ${path}: ${res.status} ${(await res.text()).slice(0, 200)}`);
  return { data: await res.json(), remaining: Number.isFinite(remaining) ? remaining : null };
}

// Strips one description; the calls left this hour, or null when nothing
// was written.
async function stripOne(token, repo, n, body) {
  const next = stripAttribution(body);
  if (next === body || next == null) return null;
  const { remaining } = await gh(token, 'PATCH', `repos/${repo}/pulls/${n}`, { body: next });
  console.log(`#${n}: attribution removed`);
  return remaining == null ? Infinity : remaining;
}

async function main() {
  const token = process.env.GITHUB_TOKEN;
  const repo = process.env.REPO;
  const one = String(process.env.PR_NUMBER || '').trim();
  if (!token || !repo) throw new Error('GITHUB_TOKEN and REPO are required');
  if (one) {
    const { data } = await gh(token, 'GET', `repos/${repo}/pulls/${one}`);
    if ((await stripOne(token, repo, one, data.body)) == null) console.log(`#${one}: nothing to remove`);
    return;
  }
  // Every pull request, oldest page last. The workflow token has about a
  // thousand calls an hour: when they run low the sweep stops, and the next
  // run (it is safe to repeat) carries on.
  let page = 1, seen = 0, fixed = 0, left = Infinity;
  sweep: for (;;) {
    const { data, remaining } = await gh(token, 'GET', `repos/${repo}/pulls?state=all&per_page=100&page=${page}`);
    if (remaining != null) left = remaining;
    if (!Array.isArray(data) || !data.length) break;
    for (const pr of data) {
      seen++;
      if (left < 25) { console.log(`stopping at #${pr.number}: ${left} calls left this hour, run again later`); break sweep; }
      const r = await stripOne(token, repo, pr.number, pr.body);
      if (r != null) { fixed++; left = r; }
    }
    page++;
  }
  console.log(`swept ${seen} pull requests, ${fixed} cleaned`);
}

if (require.main === module) main().catch((e) => { console.error(e.message || e); process.exitCode = 1; });

module.exports = { stripAttribution };
